<?php $title='Clientes';require __DIR__.'/../layouts/header.php'; ?><div class="app-shell"><?php require __DIR__.'/../layouts/sidebar.php'; ?><main class="main"><header class="page-head"><div><div class="breadcrumb">GESTIÓN / <strong>Clientes</strong></div><h1>Clientes</h1><p>Administra los datos y preferencias de los viajeros.</p></div></header><?php require __DIR__.'/../layouts/flash.php'; ?><section class="panel"><div class="panel-heading"><div><h2>Directorio de clientes</h2><p><?=count($clients)?> registro(s) encontrados</p></div><form class="search-form" method="get"><input type="hidden" name="page" value="clients"><input name="q" placeholder="Buscar nombre, correo o teléfono…" value="<?=e($_GET['q']??'')?>"><button class="btn secondary">Buscar</button></form></div><form class="inline-form" method="post" action="index.php?page=client-save"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="name" placeholder="Nombre completo *" required><input type="email" name="email" placeholder="Correo electrónico"><input name="phone" placeholder="Teléfono / WhatsApp"><input name="country" placeholder="País"><input name="preferences" placeholder="Preferencias de viaje"><button class="btn primary">＋ Añadir cliente</button></form><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>CONTACTO</th><th>PAÍS</th><th>PREFERENCIAS</th><th>REGISTRO</th><th>ACCIÓN</th></tr></thead><tbody><?php foreach($clients as $c): ?><tr><td><strong><?=e($c['name'])?></strong></td><td><?=e($c['email'])?><small class="subcell"><?=e($c['phone'])?></small></td><td><?=e($c['country'])?></td><td><?=e($c['preferences'])?></td><td><?=e(substr($c['created_at'],0,10))?></td><td><?php if(($_SESSION['user']['role']??'')==='Administrador'): ?><form method="post" action="index.php?page=client-delete" onsubmit="return confirm('¿Eliminar este cliente?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="icon-btn danger" title="Eliminar">⌫</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; if(!$clients): ?><tr><td colspan="6" class="empty">No se encontraron clientes.</td></tr><?php endif; ?></tbody></table></div></section><footer class="page-footer">NETA Gestión Integral <span>Clientes y CRM básico</span></footer></main></div><?php require __DIR__.'/../layouts/footer.php'; ?>
